@props({'variant': 'default', 'size': 'default', 'type': 'button'})
<button type="{{ type }}" data-slot="button" {{ attributes.cn(
    "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    {
        'default': 'bg-primary text-primary-foreground shadow-xs hover:bg-primary/90',
        'destructive': 'bg-destructive text-white shadow-xs hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:bg-destructive/60',
        'outline': 'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        'secondary': 'bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80',
        'ghost': 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        'link': 'text-primary underline-offset-4 hover:underline',
    }[variant],
    {
        'default': 'h-9 px-4 py-2 has-[>svg]:px-3',
        'sm': 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        'lg': 'h-10 rounded-md px-6 has-[>svg]:px-4',
        'icon': 'size-9',
    }[size],
) }}>{{ slot }}</button>

@props({'variant': 'default', 'size': 'default', 'href': '#'})
<a href="{{ href }}" data-slot="button" {{ attributes.cn(
    "inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-disabled:pointer-events-none aria-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    {
        'default': 'bg-primary text-primary-foreground shadow-xs hover:bg-primary/90',
        'destructive': 'bg-destructive text-white shadow-xs hover:bg-destructive/90 dark:bg-destructive/60',
        'outline': 'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        'secondary': 'bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80',
        'ghost': 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        'link': 'text-primary underline-offset-4 hover:underline',
    }[variant],
    {
        'default': 'h-9 px-4 py-2 has-[>svg]:px-3',
        'sm': 'h-8 gap-1.5 rounded-md px-3 has-[>svg]:px-2.5',
        'lg': 'h-10 rounded-md px-6 has-[>svg]:px-4',
        'icon': 'size-9',
    }[size],
) }}>{{ slot }}</a>

@props({'variant': 'default'})
<span data-slot="badge" {{ attributes.cn(
    "inline-flex w-fit shrink-0 items-center justify-center gap-1 overflow-hidden whitespace-nowrap rounded-md border px-2 py-0.5 text-xs font-medium transition-[color,box-shadow] [&>svg]:pointer-events-none [&>svg]:size-3",
    {
        'default': 'border-transparent bg-primary text-primary-foreground',
        'secondary': 'border-transparent bg-secondary text-secondary-foreground',
        'destructive': 'border-transparent bg-destructive text-white dark:bg-destructive/60',
        'success': 'border-transparent bg-success text-success-foreground',
        'warning': 'border-transparent bg-warning text-warning-foreground',
        'outline': 'text-foreground',
    }[variant],
) }}>{{ slot }}</span>

@props({'variant': 'default'})
<div role="alert" data-slot="alert" {{ attributes.cn(
    "relative grid w-full grid-cols-[0_1fr] content-start items-start gap-y-0.5 rounded-lg border px-4 py-3 text-sm has-[>svg]:grid-cols-[calc(var(--spacing)*4)_1fr] has-[>svg]:gap-x-3 [&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current",
    {
        'default': 'bg-card text-card-foreground',
        'destructive': 'bg-card text-destructive [&>svg]:text-current *:data-[slot=alert-description]:text-destructive/90',
        'success': 'bg-card text-success *:data-[slot=alert-description]:text-success/90',
        'warning': 'bg-card text-warning *:data-[slot=alert-description]:text-warning/90',
    }[variant],
) }}>{{ slot }}</div>

@props({'src': None, 'alt': '', 'fallback': ''})
<span data-slot="avatar" {{ attributes.cn("relative flex size-8 shrink-0 overflow-hidden rounded-full") }}>
  @if(src)
  <img src="{{ src }}" alt="{{ alt }}" class="aspect-square size-full object-cover" />
  @else
  <span class="flex size-full items-center justify-center rounded-full bg-muted text-xs font-medium">{{ fallback }}</span>
  @endif
</span>

@props({'type': 'text'})
<input type="{{ type }}" data-slot="input" {{ attributes.cn(
    "flex h-9 w-full min-w-0 rounded-md border border-input bg-transparent px-3 py-1 text-base shadow-xs transition-[color,box-shadow] outline-none selection:bg-primary selection:text-primary-foreground file:inline-flex file:h-7 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-input/30",
    "focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50",
    "aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40",
) }} />

@props({'orientation': 'horizontal'})
<div role="separator" aria-orientation="{{ orientation }}" data-slot="separator" {{ attributes.cn(
    "shrink-0 bg-border",
    {'horizontal': 'h-px w-full', 'vertical': 'h-full w-px self-stretch'}[orientation],
) }}></div>

@props({'href': None, 'variant': 'default'})
<a role="menuitem" data-slot="dropdown-menu-item" @if(href)href="{{ href }}"@endif tabindex="0" {{ attributes.cn(
    "relative flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground aria-disabled:pointer-events-none aria-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    {'default': '', 'destructive': 'text-destructive hover:bg-destructive/10 focus:bg-destructive/10 dark:hover:bg-destructive/20'}[variant],
) }}>{{ slot }}</a>

@props({'text': '', 'side': 'top'})
<span data-slot="tooltip" class="group/tooltip relative inline-flex">
  {{ slot }}
  <span role="tooltip" {{ attributes.cn(
      "pointer-events-none absolute z-50 w-max max-w-xs rounded-md bg-foreground px-3 py-1.5 text-xs text-background opacity-0 transition-opacity group-hover/tooltip:opacity-100 group-focus-within/tooltip:opacity-100",
      {
          'top': 'bottom-full left-1/2 mb-2 -translate-x-1/2',
          'bottom': 'top-full left-1/2 mt-2 -translate-x-1/2',
          'left': 'right-full top-1/2 mr-2 -translate-y-1/2',
          'right': 'left-full top-1/2 ml-2 -translate-y-1/2',
      }[side],
  ) }}>{{ text }}</span>
</span>

@props({'position': 'bottom-right', 'duration': 4000})
<div data-slot="toaster" aria-live="polite"
  x-data="{
    toasts: [],
    add(detail) {
      const toast = { id: Date.now() + Math.random(), variant: 'default', ...(typeof detail === 'string' ? { title: detail } : detail) };
      this.toasts.push(toast);
      setTimeout(() => this.remove(toast.id), toast.duration || {{ duration }});
    },
    remove(id) { this.toasts = this.toasts.filter(t => t.id !== id) },
  }"
  x-init="window.toast = (detail) => window.dispatchEvent(new CustomEvent('toast', { detail }))"
  x-on:toast.window="add($event.detail)"
  {{ attributes.cn(
    "pointer-events-none fixed z-[100] flex w-full max-w-sm flex-col gap-2 p-4",
    {
        'top-left': 'top-0 left-0', 'top-center': 'top-0 left-1/2 -translate-x-1/2', 'top-right': 'top-0 right-0',
        'bottom-left': 'bottom-0 left-0', 'bottom-center': 'bottom-0 left-1/2 -translate-x-1/2', 'bottom-right': 'bottom-0 right-0',
    }[position],
  ) }}>
  <template x-for="toast in toasts" x-bind:key="toast.id">
    <div x-transition.opacity role="status"
      class="pointer-events-auto flex w-full items-start gap-3 rounded-lg border bg-popover p-4 text-sm text-popover-foreground shadow-lg"
      x-bind:class="{ 'border-destructive/50 text-destructive': toast.variant === 'destructive', 'border-success/50': toast.variant === 'success' }">
      <div class="grid flex-1 gap-1">
        <p class="font-semibold" x-text="toast.title"></p>
        <p class="text-muted-foreground" x-show="toast.description" x-text="toast.description"></p>
      </div>
      <button type="button" class="cursor-pointer opacity-60 hover:opacity-100" x-on:click="remove(toast.id)" aria-label="Close">
        <svg class="size-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>
      </button>
    </div>
  </template>
</div>

@props({'type': 'single', 'value': ''})
<div role="group" data-slot="toggle-group"
  x-data="{
    type: '{{ type }}',
    value: '{{ value }}'.split(',').filter(Boolean),
    has(v) { return this.value.includes(v) },
    toggle(v) {
      if (this.type === 'single') { this.value = this.has(v) ? [] : [v]; return }
      this.value = this.has(v) ? this.value.filter(x => x !== v) : [...this.value, v];
    },
  }"
  {{ attributes.cn("flex w-fit items-center rounded-md [&>*]:rounded-none [&>*:first-child]:rounded-l-md [&>*:last-child]:rounded-r-md") }}>{{ slot }}</div>

@props({'value': '', 'variant': 'default'})
<button type="button" data-slot="toggle-group-item" x-on:click="toggle('{{ value }}')"
  x-bind:aria-pressed="has('{{ value }}')" x-bind:data-state="has('{{ value }}') ? 'on' : 'off'" {{ attributes.cn(
    "inline-flex h-9 min-w-9 flex-1 shrink-0 cursor-pointer items-center justify-center gap-2 px-2 text-sm font-medium whitespace-nowrap transition-[color,box-shadow] outline-none hover:bg-muted hover:text-muted-foreground focus:z-10 focus-visible:z-10 focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    {'default': 'bg-transparent', 'outline': 'border border-input bg-transparent shadow-xs hover:bg-accent hover:text-accent-foreground [&:not(:first-child)]:border-l-0'}[variant],
) }}>{{ slot }}</button>

@props({'orientation': 'horizontal'})
<div role="group" data-slot="button-group" data-orientation="{{ orientation }}" {{ attributes.cn(
    "flex w-fit items-stretch [&>*]:focus-visible:relative [&>*]:focus-visible:z-10",
    {
        'horizontal': '[&>*:not(:first-child)]:rounded-l-none [&>*:not(:first-child)]:border-l-0 [&>*:not(:last-child)]:rounded-r-none',
        'vertical': 'flex-col [&>*:not(:first-child)]:rounded-t-none [&>*:not(:first-child)]:border-t-0 [&>*:not(:last-child)]:rounded-b-none',
    }[orientation],
) }}>{{ slot }}</div>

@props({'href': '#', 'active': False})
<a href="{{ href }}" data-slot="pagination-link" data-active="{{ str(bool(active)).lower() }}" @if(active)aria-current="page"@endif {{ attributes.cn(
    "inline-flex shrink-0 cursor-pointer items-center justify-center gap-1 whitespace-nowrap rounded-md text-sm font-medium transition-all outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 size-9",
    {
        'True': 'border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:border-input dark:bg-input/30',
        'False': 'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
    }[str(bool(active))],
) }}>{{ slot }}</a>

@props({'variant': 'default'})
<div data-slot="empty-media" data-variant="{{ variant }}" {{ attributes.cn(
    "mb-2 flex shrink-0 items-center justify-center [&_svg]:pointer-events-none [&_svg]:shrink-0",
    {'default': 'bg-transparent', 'icon': "size-10 rounded-lg bg-muted text-foreground [&_svg:not([class*='size-'])]:size-6"}[variant],
) }}>{{ slot }}</div>

@props({'orientation': 'vertical', 'invalid': False, 'errors': None, 'name': ''})
<div role="group" data-slot="field" data-orientation="{{ orientation }}" data-invalid="{{ str(bool(invalid)).lower() }}" data-error="@if(errors and name)@error(name)true@enderror@endif" {{ attributes.cn(
    "group/field flex w-full gap-3 data-[invalid=true]:text-destructive data-[error=true]:text-destructive",
    {
        'vertical': 'flex-col [&>*]:w-full',
        'horizontal': 'flex-row items-center [&>[data-slot=field-label]]:flex-auto',
    }[orientation],
) }}>{{ slot }}</div>

@props({'trigger': '', 'align': 'center'})
<span data-slot="hover-card" class="group/hover-card relative inline-flex">
  {{ trigger }}
  <div data-slot="hover-card-content" {{ attributes.cn(
      "invisible absolute top-full z-50 mt-2 w-64 rounded-md border bg-popover p-4 text-popover-foreground opacity-0 shadow-md transition-[opacity,visibility] delay-200 duration-150 group-focus-within/hover-card:visible group-focus-within/hover-card:opacity-100 group-hover/hover-card:visible group-hover/hover-card:opacity-100",
      {'start': 'left-0', 'center': 'left-1/2 -translate-x-1/2', 'end': 'right-0'}[align],
  ) }}>{{ slot }}</div>
</span>

@props({'heading': ''})
<div role="group" data-slot="command-group" x-show="[...$el.querySelectorAll('[data-slot=command-item]')].some(i => match(i.textContent))" {{ attributes.cn("overflow-hidden p-1 text-foreground") }}>
  <div data-slot="command-group-heading" class="px-2 py-1.5 text-xs font-medium text-muted-foreground">{{ heading }}</div>
  {{ slot }}
</div>

@props({'name': 'code', 'length': 6})
<div data-slot="input-otp"
  x-data="{
    digits: Array({{ int(length) }}).fill(''),
    boxes() { return [...this.$root.querySelectorAll('[data-slot=input-otp-slot]')] },
    put(i, value) {
      const chars = value.replace(/\s/g, '').split('');
      if (!chars.length) { this.digits[i] = ''; return }
      chars.forEach((c, k) => { if (i + k < this.digits.length) this.digits[i + k] = c });
      const next = this.boxes()[Math.min(i + chars.length, this.digits.length - 1)];
      if (next) next.focus();
    },
    back(i, e) { if (!this.digits[i] && i > 0) { e.preventDefault(); this.digits[i - 1] = ''; this.boxes()[i - 1].focus() } },
  }"
  {{ attributes.cn("flex items-center has-disabled:opacity-50") }}>
  <input type="hidden" name="{{ name }}" x-bind:value="digits.join('')" />
  <template x-for="(digit, i) in digits" x-bind:key="i">
    <input data-slot="input-otp-slot" inputmode="numeric" autocomplete="one-time-code" maxlength="6" aria-label="Digit"
      x-bind:value="digit" x-on:input="put(i, $event.target.value); $event.target.value = digits[i]"
      x-on:keydown.backspace="back(i, $event)" x-on:focus="$event.target.select()"
      class="relative -ml-px flex size-9 items-center justify-center border border-input bg-transparent text-center text-sm shadow-xs transition-all outline-none first:ml-0 first:rounded-l-md last:rounded-r-md focus:z-10 focus:border-ring focus:ring-[3px] focus:ring-ring/50 dark:bg-input/30" />
  </template>
</div>

@props({'href': None, 'active': False, 'size': 'default', 'variant': 'default', 'tooltip': ''})
<a data-slot="sidebar-menu-button" @if(href)href="{{ href }}"@endif tabindex="0" @if(active)aria-current="page"@endif data-active="{{ str(bool(active)).lower() }}" data-size="{{ size }}" {{ attributes.cn(
    "group/menu-button peer/menu-button relative flex w-full cursor-pointer items-center gap-2 rounded-md p-2 text-left text-sm whitespace-nowrap ring-sidebar-ring outline-hidden transition-[width,height,padding] select-none",
    "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground aria-disabled:pointer-events-none aria-disabled:opacity-50",
    "data-[active=true]:bg-sidebar-accent data-[active=true]:font-medium data-[active=true]:text-sidebar-accent-foreground group-has-data-[slot=sidebar-menu-action]/menu-item:pr-8",
    "[&>span:not([data-slot])]:min-w-0 [&>span:not([data-slot])]:truncate [&>svg]:size-4 [&>svg]:shrink-0",
    "md:group-data-[collapsible=icon]/sidebar:size-8! md:group-data-[collapsible=icon]/sidebar:p-2! md:group-data-[collapsible=icon]/sidebar:[&>:not(:first-child):not([data-slot=sidebar-tooltip])]:hidden",
    {
        'default': '',
        'outline': 'bg-background shadow-[0_0_0_1px_var(--sidebar-border)] hover:shadow-[0_0_0_1px_var(--sidebar-accent)]',
    }[variant],
    {
        'default': 'h-8 text-sm',
        'sm': 'h-7 text-xs',
        'lg': 'h-12 text-sm md:group-data-[collapsible=icon]/sidebar:p-0!',
    }[size],
) }}>{{ slot }}@if(tooltip)<span data-slot="sidebar-tooltip" role="tooltip" class="pointer-events-none absolute top-1/2 left-full z-50 ml-3 hidden w-max -translate-y-1/2 rounded-md bg-foreground px-3 py-1.5 text-xs font-normal text-background opacity-0 transition-opacity group-hover/menu-button:opacity-100 group-focus-visible/menu-button:opacity-100 md:group-data-[collapsible=icon]/sidebar:block">{{ tooltip }}</span>@endif</a>

@props({'show_on_hover': False})
<button type="button" data-slot="sidebar-menu-action" {{ attributes.cn(
    "absolute top-1.5 right-1 flex aspect-square w-5 cursor-pointer items-center justify-center rounded-md p-0 text-sidebar-foreground ring-sidebar-ring outline-hidden transition-transform peer-hover/menu-button:text-sidebar-accent-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 after:absolute after:-inset-2 md:after:hidden md:group-data-[collapsible=icon]/sidebar:hidden [&>svg]:size-4 [&>svg]:shrink-0",
    {'True': 'group-focus-within/menu-item:opacity-100 group-hover/menu-item:opacity-100 peer-data-[active=true]/menu-button:text-sidebar-accent-foreground md:opacity-0', 'False': ''}[str(bool(show_on_hover))],
) }}>{{ slot }}</button>

@props({'show_icon': False, 'width': '70%'})
<div data-slot="sidebar-menu-skeleton" {{ attributes.cn("flex h-8 items-center gap-2 rounded-md px-2") }}>
  @if(show_icon)<div class="size-4 animate-pulse rounded-md bg-sidebar-accent"></div>@endif
  <div class="h-4 max-w-(--skeleton-width) flex-1 animate-pulse rounded-md bg-sidebar-accent" style="--skeleton-width: {{ width }}"></div>
</div>

@props({'href': None, 'active': False, 'size': 'md'})
<a data-slot="sidebar-menu-sub-button" @if(href)href="{{ href }}"@endif tabindex="0" @if(active)aria-current="page"@endif data-active="{{ str(bool(active)).lower() }}" data-size="{{ size }}" {{ attributes.cn(
    "flex h-7 min-w-0 -translate-x-px cursor-pointer items-center gap-2 overflow-hidden rounded-md px-2 text-sidebar-foreground ring-sidebar-ring outline-hidden hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:ring-2 active:bg-sidebar-accent active:text-sidebar-accent-foreground aria-disabled:pointer-events-none aria-disabled:opacity-50 data-[active=true]:bg-sidebar-accent data-[active=true]:text-sidebar-accent-foreground [&>span:last-child]:truncate [&>svg]:size-4 [&>svg]:shrink-0 [&>svg]:text-sidebar-accent-foreground",
    {'sm': 'text-xs', 'md': 'text-sm'}[size],
) }}>{{ slot }}</a>

@props({'value': ''})
<button type="button" role="option" data-slot="combobox-item" data-value="{{ value }}" x-show="match($el.textContent)"
  x-bind:aria-selected="value === '{{ value }}'" x-on:click="pick('{{ value }}', $el.textContent.trim())" {{ attributes.cn(
    "relative flex w-full cursor-pointer items-center gap-2 rounded-sm py-1.5 pr-8 pl-2 text-left text-sm outline-hidden select-none hover:bg-accent hover:text-accent-foreground focus:bg-accent focus:text-accent-foreground disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
) }}>{{ slot }}<span class="absolute right-2 flex size-3.5 items-center justify-center" x-show="value === '{{ value }}'"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg></span></button>

@props({'value': '', 'name': '', 'locale': 'en-US', 'week_start': 0, 'min': '', 'max': ''})
<div data-slot="calendar"
  x-data="{
    value: '{{ value }}', locale: '{{ locale }}', weekStart: {{ int(week_start) }}, min: '{{ min }}', max: '{{ max }}',
    month: null,
    iso(d) { return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0') },
    parse(s) { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d) },
    init() { const base = this.value ? this.parse(this.value) : new Date(); this.month = new Date(base.getFullYear(), base.getMonth(), 1) },
    get title() { return this.month.toLocaleDateString(this.locale, { month: 'long', year: 'numeric' }) },
    get weekdays() {
      const ref = new Date(2024, 0, 7 + this.weekStart);
      return [...Array(7)].map((_, i) => new Date(ref.getFullYear(), ref.getMonth(), ref.getDate() + i).toLocaleDateString(this.locale, { weekday: 'short' }).slice(0, 2));
    },
    get days() {
      const first = this.month, offset = (first.getDay() - this.weekStart + 7) % 7;
      return [...Array(42)].map((_, i) => {
        const d = new Date(first.getFullYear(), first.getMonth(), 1 - offset + i);
        return { iso: this.iso(d), day: d.getDate(), outside: d.getMonth() !== first.getMonth() };
      });
    },
    disabled(iso) { return Boolean((this.min && iso < this.min) || (this.max && iso > this.max)) },
    shift(n) { this.month = new Date(this.month.getFullYear(), this.month.getMonth() + n, 1) },
    select(iso) { if (this.disabled(iso)) return; this.value = iso; this.$dispatch('calendar-select', iso) },
    focusDay(iso) { this.$nextTick(() => { const b = this.$root.querySelector(`[data-day='${iso}']`); if (b) b.focus() }) },
    key(e, iso) {
      const step = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key];
      if (!step) return;
      e.preventDefault();
      const d = this.parse(iso); d.setDate(d.getDate() + step);
      if (d.getMonth() !== this.month.getMonth()) this.month = new Date(d.getFullYear(), d.getMonth(), 1);
      this.focusDay(this.iso(d));
    },
  }"
  {{ attributes.cn("w-fit p-3") }}>
  <input type="hidden" name="{{ name }}" x-bind:value="value" x-bind:disabled="!'{{ name }}'" />
  <div class="relative flex h-8 items-center justify-center">
